package com.secureapp.crypto

import javax.crypto.{Cipher, SecretKeyFactory, Mac}
import javax.crypto.spec.{IvParameterSpec, PBEKeySpec, SecretKeySpec}
import java.security.SecureRandom
import java.util.Base64
import scala.util.{Try, Success, Failure}

object CryptoConfig {
  val ALGORITHM = "AES/CBC/PKCS5Padding"
  val KEY_ALGORITHM = "AES"
  val KEY_DERIVATION = "PBKDF2WithHmacSHA256"
  val HMAC_ALGORITHM = "HmacSHA256"
  val KEY_LENGTH = 256
  val ITERATIONS = 100000
  val IV_LENGTH = 16
  val HMAC_LENGTH = 32
}

class SecureMessageProcessor(masterKey: Array[Byte]) {
  import CryptoConfig._

  private val encKey = deriveKey(masterKey, "encryption".getBytes)
  private val macKey = deriveKey(masterKey, "authentication".getBytes)

  private def deriveKey(master: Array[Byte], context: Array[Byte]): SecretKeySpec = {
    val factory = SecretKeyFactory.getInstance(KEY_DERIVATION)
    val spec = new PBEKeySpec(
      master.map(_.toChar),
      context,
      ITERATIONS,
      KEY_LENGTH
    )
    new SecretKeySpec(factory.generateSecret(spec).getEncoded, KEY_ALGORITHM)
  }

  private def computeHmac(data: Array[Byte]): Array[Byte] = {
    val mac = Mac.getInstance(HMAC_ALGORITHM)
    mac.init(macKey)
    mac.doFinal(data)
  }

  private def constantTimeCompare(a: Array[Byte], b: Array[Byte]): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    for (i <- a.indices) {
      result |= (a(i) ^ b(i))
    }
    result == 0
  }

  def encrypt(plaintext: Array[Byte]): String = {
    val random = new SecureRandom()
    val iv = new Array[Byte](IV_LENGTH)
    random.nextBytes(iv)

    val cipher = Cipher.getInstance(ALGORITHM)
    cipher.init(Cipher.ENCRYPT_MODE, encKey, new IvParameterSpec(iv))
    val ciphertext = cipher.doFinal(plaintext)

    val payload = iv ++ ciphertext
    val hmac = computeHmac(payload)
    Base64.getEncoder.encodeToString(payload ++ hmac)
  }

  def decrypt(encoded: String): Either[String, Array[Byte]] = {
    val decoded = Try(Base64.getDecoder.decode(encoded)) match {
      case Success(d) => d
      case Failure(_) => return Left("invalid_encoding")
    }

    if (decoded.length < IV_LENGTH + HMAC_LENGTH + 1) {
      return Left("invalid_message")
    }

    val payload = decoded.slice(0, decoded.length - HMAC_LENGTH)
    val receivedHmac = decoded.slice(decoded.length - HMAC_LENGTH, decoded.length)
    val computedHmac = computeHmac(payload)

    if (!constantTimeCompare(receivedHmac, computedHmac)) {
      return Left("invalid_message")
    }

    val iv = payload.slice(0, IV_LENGTH)
    val ciphertext = payload.slice(IV_LENGTH, payload.length)

    val cipher = Cipher.getInstance(ALGORITHM)
    cipher.init(Cipher.DECRYPT_MODE, encKey, new IvParameterSpec(iv))

    Try(cipher.doFinal(ciphertext)) match {
      case Success(plaintext) => Right(plaintext)
      case Failure(_) => Left("decryption_failed")
    }
  }
}

// Kubernetes health check and message processing endpoint
object MessageService {
  private lazy val processor = new SecureMessageProcessor(
    sys.env.getOrElse("MASTER_KEY", "default-dev-key").getBytes
  )

  sealed trait DecryptionResult
  case class DecryptionSuccess(data: Array[Byte], processingTimeNs: Long) extends DecryptionResult
  case class DecryptionError(error: String, processingTimeNs: Long) extends DecryptionResult

  def processMessage(encodedMessage: String): DecryptionResult = {
    val startTime = System.nanoTime()
    val result = processor.decrypt(encodedMessage)
    val elapsed = System.nanoTime() - startTime

    result match {
      case Right(data) => DecryptionSuccess(data, elapsed)
      case Left(err) => DecryptionError(err, elapsed)
    }
  }

  def handleRequest(body: String): (Int, String) = {
    if (body.isEmpty) {
      return (400, "{\"error\": \"empty_body\"}")
    }

    processMessage(body) match {
      case DecryptionSuccess(data, timeNs) =>
        (200, s"""{"status": "ok", "length": ${data.length}, "processing_ns": $timeNs}""")
      case DecryptionError(error, timeNs) =>
        (400, s"""{"error": "$error", "processing_ns": $timeNs}""")
    }
  }

  // Kubernetes liveness probe
  def healthCheck(): (Int, String) = (200, "{\"status\": \"healthy\"}")

  // Kubernetes readiness probe - verifies crypto subsystem
  def readinessCheck(): (Int, String) = {
    val testData = "readiness-probe-test".getBytes
    val encrypted = processor.encrypt(testData)
    processor.decrypt(encrypted) match {
      case Right(decrypted) if java.util.Arrays.equals(decrypted, testData) =>
        (200, "{\"status\": \"ready\"}")
      case _ =>
        (503, "{\"status\": \"not_ready\"}")
    }
  }
}
